using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.SweetCicely;

/// <summary>
/// Sweet cicely, a tall herb with soft, fern-like leaves and white umbels that tastes of anise, in the Mistlands.
/// Model: generated by AssetSource/Tools/make_forage_models.py.
/// </summary>
public class SweetCicely : ForageableBase
{
    /// <summary>
    /// Prefab name of the sweet cicely item.
    /// </summary>
    public const string PrefabName = "WhiteHiltSweetCicely";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Sweet Cicely";

    /// <inheritdoc/>
    protected override string Description => "Soft, fern-like leaves and white flowers that taste of anise. It sweetens without honey and seasons meat.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Thistle";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Thistle";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.Mistlands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 2,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 3,
        GroupRadius = 3f,
        MinAltitude = 1f,
        MaxTilt = 30f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, "sweetcicely", 0.85f);
    }

    /// <inheritdoc/>
    protected override void ApplyPickableVisual(GameObject pickablePrefab, Pickable pickable)
    {
        RemoveGlow(pickablePrefab);
        base.ApplyPickableVisual(pickablePrefab, pickable);
    }
}
